cash_flows = [-1000, 400, 400, 400]   # t = 0, 1, 2, 3

def npv(rate, cfs):
    return sum(cf / (1 + rate) ** t for t, cf in enumerate(cfs))

def irr(cfs, lo=-0.5, hi=2.0):         # bisection: NPV falls as rate rises
    for _ in range(100):
        mid = (lo + hi) / 2
        if npv(mid, cfs) > 0:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2

print(round(npv(0.08, cash_flows), 2))  # 30.84
print(round(irr(cash_flows), 4))        # ~0.097, i.e. 9.70%
